from contextlib import suppress
from io import TextIOWrapper

from . import abc


class SpecLoaderAdapter:
    """
    Adapt a package spec to adapt the underlying loader.
    """

    def __init__(self, spec, adapter=lambda spec: spec.loader):
        """函数 __init__：处理 spec, adapter 相关逻辑。"""
        self.spec = spec
        self.loader = adapter(spec)

    def __getattr__(self, name):
        """函数 __getattr__：处理 name 相关逻辑。"""
        return getattr(self.spec, name)


class TraversableResourcesLoader:
    """
    Adapt a loader to provide TraversableResources.
    """

    def __init__(self, spec):
        """函数 __init__：处理 spec 相关逻辑。"""
        self.spec = spec

    def get_resource_reader(self, name):
        """函数 get_resource_reader：处理 name 相关逻辑。"""
        return CompatibilityFiles(self.spec)._native()


def _io_wrapper(file, mode='r', *args, **kwargs):
    """函数 _io_wrapper：处理 file, mode, *args, **kwargs 相关逻辑。"""
    if mode == 'r':
        return TextIOWrapper(file, *args, **kwargs)
    elif mode == 'rb':
        return file
    raise ValueError(
        "Invalid mode value '{}', only 'r' and 'rb' are supported".format(mode)
    )


class CompatibilityFiles:
    """
    Adapter for an existing or non-existent resource reader
    to provide a compatibility .files().
    """

    class SpecPath(abc.Traversable):
        """
        Path tied to a module spec.
        Can be read and exposes the resource reader children.
        """

        def __init__(self, spec, reader):
            """函数 __init__：处理 spec, reader 相关逻辑。"""
            self._spec = spec
            self._reader = reader

        def iterdir(self):
            """函数 iterdir：核心业务逻辑。"""
            if not self._reader:
                return iter(())
            return iter(
                CompatibilityFiles.ChildPath(self._reader, path)
                for path in self._reader.contents()
            )

        def is_file(self):
            """函数 is_file：核心业务逻辑。"""
            return False

        is_dir = is_file

        def joinpath(self, other):
            """函数 joinpath：处理 other 相关逻辑。"""
            if not self._reader:
                return CompatibilityFiles.OrphanPath(other)
            return CompatibilityFiles.ChildPath(self._reader, other)

        @property
        def name(self):
            """函数 name：核心业务逻辑。"""
            return self._spec.name

        def open(self, mode='r', *args, **kwargs):
            """函数 open：处理 mode, *args, **kwargs 相关逻辑。"""
            return _io_wrapper(self._reader.open_resource(None), mode, *args, **kwargs)

    class ChildPath(abc.Traversable):
        """
        Path tied to a resource reader child.
        Can be read but doesn't expose any meaningful children.
        """

        def __init__(self, reader, name):
            """函数 __init__：处理 reader, name 相关逻辑。"""
            self._reader = reader
            self._name = name

        def iterdir(self):
            """函数 iterdir：核心业务逻辑。"""
            return iter(())

        def is_file(self):
            """函数 is_file：核心业务逻辑。"""
            return self._reader.is_resource(self.name)

        def is_dir(self):
            """函数 is_dir：核心业务逻辑。"""
            return not self.is_file()

        def joinpath(self, other):
            """函数 joinpath：处理 other 相关逻辑。"""
            return CompatibilityFiles.OrphanPath(self.name, other)

        @property
        def name(self):
            """函数 name：核心业务逻辑。"""
            return self._name

        def open(self, mode='r', *args, **kwargs):
            """函数 open：处理 mode, *args, **kwargs 相关逻辑。"""
            return _io_wrapper(
                self._reader.open_resource(self.name), mode, *args, **kwargs
            )

    class OrphanPath(abc.Traversable):
        """
        Orphan path, not tied to a module spec or resource reader.
        Can't be read and doesn't expose any meaningful children.
        """

        def __init__(self, *path_parts):
            """函数 __init__：处理 *path_parts 相关逻辑。"""
            if len(path_parts) < 1:
                raise ValueError('Need at least one path part to construct a path')
            self._path = path_parts

        def iterdir(self):
            """函数 iterdir：核心业务逻辑。"""
            return iter(())

        def is_file(self):
            """函数 is_file：核心业务逻辑。"""
            return False

        is_dir = is_file

        def joinpath(self, other):
            """函数 joinpath：处理 other 相关逻辑。"""
            return CompatibilityFiles.OrphanPath(*self._path, other)

        @property
        def name(self):
            """函数 name：核心业务逻辑。"""
            return self._path[-1]

        def open(self, mode='r', *args, **kwargs):
            """函数 open：处理 mode, *args, **kwargs 相关逻辑。"""
            raise FileNotFoundError("Can't open orphan path")

    def __init__(self, spec):
        """函数 __init__：处理 spec 相关逻辑。"""
        self.spec = spec

    @property
    def _reader(self):
        """函数 _reader：核心业务逻辑。"""
        with suppress(AttributeError):
            return self.spec.loader.get_resource_reader(self.spec.name)

    def _native(self):
        """
        Return the native reader if it supports files().
        """
        reader = self._reader
        return reader if hasattr(reader, 'files') else self

    def __getattr__(self, attr):
        """函数 __getattr__：处理 attr 相关逻辑。"""
        return getattr(self._reader, attr)

    def files(self):
        """函数 files：核心业务逻辑。"""
        return CompatibilityFiles.SpecPath(self.spec, self._reader)


def wrap_spec(package):
    """
    Construct a package spec with traversable compatibility
    on the spec/loader/reader.
    """
    return SpecLoaderAdapter(package.__spec__, TraversableResourcesLoader)
